    if len(sys.argv) < 3:
        return

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load data from lca_disclosure.csv
    data_records = []
    csv_path = os.path.join(packet_dir, 'lca_disclosure.csv')
    if os.path.exists(csv_path):
        with open(csv_path, 'r', newline='') as f:
            reader = csv.DictReader(f)
            for row in reader:
                data_records.append(row)

    results = {}

    for pair_str in manifest['pairs']:
        rule_id, entity_id = pair_str.split('::')
        facts_to_find = manifest['facts'].get(rule_id, [])

        # Find the record for this entity
        # The entity_id is the CASE_NUMBER
        record = next((r for r in data_records if r['CASE_NUMBER'] == entity_id), None)

        pair_result = {}

        if not record:
            # If no record found, all facts are ABSENT
            for fact in facts_to_find:
                pair_result[fact] = "ABSENT"
        else:
            for fact in facts_to_find:
                if rule_id == 'lca.wage_105':
                    if fact == 'offered wage':
                        val = record.get('WAGE_RATE_OF_PAY_FROM', '').strip()
                        if val == '':
                            pair_result[fact] = "ABSENT"
                        else:
                            pair_result[fact] = [f"{float(val):.2f}", "lca_disclosure"]
                    elif fact == 'prevailing wage':
                        val = record.get('PREVAILING_WAGE', '').strip()
                        if val == '':
                            pair_result[fact] = "ABSENT"
                        else:
                            pair_result[fact] = [f"{float(val):.2f}", "lca_disclosure"]

                elif rule_id == 'lca.three_years':
                    if fact == 'begin date':
                        val = excel_date(record.get('BEGIN_DATE', ''))
                        if val:
                            pair_result[fact] = [val.strftime("%Y-%m-%d"), "lca_disclosure"]
                        else:
                            pair_result[fact] = "ABSENT"
                    elif fact == 'end date':
                        val = excel_date(record.get('END_DATE', ''))
                        if val:
                            pair_result[fact] = [val.strftime("%Y-%m-%d"), "lca_disclosure"]
                        else:
                            pair_result[fact] = "ABSENT"

            # Check for CONFLICT (though in this specific schema, one record per entity is implied)
            # The prompt says "the entity's records hold disagreeing values". 
            # Since we only have one CSV, we assume one row per CASE_NUMBER.
            # If there were multiple rows for the same CASE_NUMBER, we would check for conflicts.
            # Let's check if there are multiple rows for this entity.
            entity_rows = [r for r in data_records if r['CASE_NUMBER'] == entity_id]
            if len(entity_rows) > 1:
                for fact in facts_to_find:
                    vals = []
                    for r in entity_rows:
                        if rule_id == 'lca.wage_105':
                            if fact == 'offered wage':
                                v = r.get('WAGE_RATE_OF_PAY_FROM', '').strip()
                                if v: vals.append(v)
                            elif fact == 'prevailing wage':
                                v = r.get('PREVAILING_WAGE', '').strip()
                                if v: vals.append(v)
                        elif rule_id == 'lca.three_years':
                            if fact == 'begin date':
                                v = excel_date(r.get('BEGIN_DATE', ''))
                                if v: vals.append(v.strftime("%Y-%m-%d"))
                            elif fact == 'end date':
                                v = excel_date(r.get('END_DATE', ''))
                                if v: vals.append(v.strftime("%Y-%m-%d"))

                    if len(set(vals)) > 1:
                        pair_result[fact] = "CONFLICT"

        results[pair_str] = pair_result

    print(json.dumps(results))

if __name__ == "__main__":
    main()
